<section class="panel"><header class="panel-head"><div><span class="eyebrow">Reusable operating models</span><h2>Starting templates with cross-relational integrations</h2></div><span class="panel-meta"><?= count(entity_system_template_catalog()) ?> templates</span></header><div class="template-grid"><?php foreach(entity_system_template_catalog()as$t): ?><article class="record-card template-card <?= $selectedTemplate===$t['code']?'active':'' ?>"><strong><?= h($t['name']) ?></strong><p><?= h($t['description']) ?></p><small>Version <?= h($t['version']) ?> · <?= count($t['services']) ?> shared service(s)</small><a class="button ghost" href="<?= h(app_url('entity-system.php?tab=templates&template='.rawurlencode($t['code']))) ?>">Preview</a></article><?php endforeach; ?></div></section>
<div class="entity-split"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Template preview</span><h2><?= h($preview['template']['name']) ?></h2></div><?= badge($preview['validation']['valid']?'validated':'exception') ?></header><p><?= h($preview['template']['description']) ?></p><div class="table-wrap"><table><thead><tr><th>Nodes</th><th>Relationships</th><th>Authorities</th><th>Canonical companies</th></tr></thead><tbody><tr><td><?= count($preview['nodes']) ?></td><td><?= count($preview['relationships']) ?></td><td><?= count($preview['authorities']) ?></td><td><?= count($preview['carryover']['company_ids']) ?></td></tr></tbody></table></div><h3>Authority blueprint</h3><div class="record-list"><?php foreach($preview['authorities']as$d=>$a): ?><article class="record-card"><strong><?= h(status_label($d)) ?></strong><small><?= h(status_label($a)) ?> authority</small></article><?php endforeach; ?></div></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Controlled application</span><h2>Apply template</h2></div></header><?php if(can('companies.administer')): ?><form class="compact-form" action="<?= h(app_url('entity-system-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="apply_template"><input type="hidden" name="template_code" value="<?= h($selectedTemplate) ?>"><input type="hidden" name="return_tab" value="templates"><label><span>Independent reviewer</span><select name="reviewer_id" required><?php foreach(data_collection('users')as$u)if((int)$u['id']!==(int)current_user()['id']&&$u['status']==='active'): ?><option value="<?= (int)$u['id'] ?>"><?= h($u['name']) ?></option><?php endif; ?></select></label><label><span>Approver</span><select name="approved_by" required><?php foreach(data_collection('users')as$u)if($u['status']==='active'): ?><option value="<?= (int)$u['id'] ?>"><?= h($u['name']) ?></option><?php endif; ?></select></label><label class="span-2"><span>Application evidence</span><textarea name="evidence_note" required>Preserve all canonical company IDs and existing transaction relationships while applying the reviewed entity template.</textarea></label><div class="span-2"><button class="button primary" type="submit">Apply Reviewed Template</button></div></form><?php else: ?><p>Template application requires company administration permission.</p><?php endif; ?></section></div>
